// ==UserScript==
// @name        【万能】全平台自动答题脚本
// @version      5.4.2
// @namespace    自动答题
// @description  支持【超星学习通】【智慧树】【职教云系列】【雨课堂】【考试星】【168网校】【继续教育类】【绎通云课堂】【九江系列】【柠檬文才】【亿学宝云】【优课学堂】【小鹅通】【安徽继续教育】 【上海开放大学】 【华侨大学自考网络助学平台】【良师在线】【和学在线】【人卫慕课】【国家开放大学】【山财培训网（继续教育）】【浙江省高等学校在线开放课程共享平台】【国地质大学远程与继续教育学院】【重庆大学网络教育学院】【浙江省高等教育自学考试网络助学平台】 【湖南高等学历继续教育】 【优学院】 【学起系列】【青书学堂】 【学堂在线】【英华学堂】【广开网络教学平台】等平台的测验考试，内置题库，自动答题功能全聚合
// @author       万能
// @match        *://*/*
// @icon         data:image/png;base64,
// @compatible   chrome firefox edge
// @grant        GM_info
// @grant        unsafeWindow
// @grant        GM_xmlhttpRequest
// @grant        GM_getResourceText
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_getResourceURL
// @run-at       document-start
// @connect      ykt.io
// @connect      localhost
// @connect      baidu.com
// @connect      cdn.jsdelivr.net
// @connect      cx.icodef.com
// @connect      tiku168.net
// @connect      scriptcat.org
// @connect      gitee.com
// @connect      *
// @resource     Img https://cdn.jsdelivr.net/npm/tiku-static-assets@1.0.0/6.png
// @resource     Table https://cdn.jsdelivr.net/npm/tiku-static-assets@1.0.0/cx_table.json
// @contributionURL   https://tiku168.net/pay
// @antifeature  payment 解锁付费题库需捐助
// ==/UserScript==
var GLOBAL = {
    delay: GM_getValue("__delay", 2e3),
    fillAnswerDelay: GM_getValue("__fillAnswerDelay", 1500),
    length: GM_getValue("__length", 450),
    answerApi: {
        tikuAdapter: data => {
            const tiku_adapter = GM_getValue("tiku_adapter");
            const url = tiku_adapter && !tiku_adapter.includes("undefined") ? tiku_adapter : "";
            if (!url) return Promise.resolve([]);
            return new Promise(resolve => {
                GM_xmlhttpRequest({
                    method: "POST",
                    url: url + (url.includes("?") ? "&" : "?") + "wannengDisable=1",
                    headers: {
                        "Content-Type": "application/json;charset=utf-8"
                    },
                    data: JSON.stringify({
                        question: data.question,
                        options: data.options,
                        type: data.type
                    }),
                    onload: function(r) {
                        try {
                            const res = JSON.parse(r.responseText);
                            resolve(res.answer.allAnswer);
                        } catch (e) {
                            resolve([]);
                        }
                    },
                    onerror: function(e) {
                        console.log(e);
                        resolve([]);
                    }
                });
            });
        }
    }
};

