    function dragModel(drag) {
        var startX, startY, initLeft, initTop, dragging = false;
        function getPos(e) {
            if (e.touches && e.touches.length) return {
                x: e.touches[0].clientX,
                y: e.touches[0].clientY
            };
            return {
                x: e.clientX,
                y: e.clientY
            };
        }
        function onStart(e) {
            dragging = true;
            drag.style.cursor = "move";
            var pos = getPos(e);
            startX = pos.x;
            startY = pos.y;
            initLeft = drag.offsetLeft;
            initTop = drag.offsetTop;
            e.preventDefault();
        }
        function onMove(e) {
            if (!dragging) return;
            var pos = getPos(e);
            var left = initLeft + pos.x - startX;
            var dy = initTop + pos.y - startY;
            var maxW = top.innerWidth * .95 - drag.offsetWidth;
            var maxH = top.innerHeight - drag.offsetHeight;
            if (left < 0) left = 0; else if (left > maxW) left = maxW;
            if (dy < 0) dy = 0; else if (dy > maxH) dy = maxH;
            drag.style.left = left + "px";
            drag.style.top = dy + "px";
        }
        function onEnd() {
            if (!dragging) return;
            dragging = false;
            drag.style.cursor = "default";
            GM_setValue("pos", drag.style.left + "," + drag.style.top);
        }
        drag.addEventListener("mousedown", onStart);
        drag.addEventListener("touchstart", onStart, {
            passive: false
        });
        top.addEventListener("mousemove", onMove);
        top.addEventListener("touchmove", onMove, {
            passive: false
        });
        top.addEventListener("mouseup", onEnd);
        top.addEventListener("touchend", onEnd);
    }
