    function parseYxbyunTest(problems) {
        return problems.map(item => {
            const type = getQuestionType(item.bigName);
            return item.smallContent.map(item => {
                let answer = [];
                let options = [];
                if (type === 2) {
                    answer.push(item.answer);
                    return {
                        question: formatString(item.content),
                        options: options,
                        type: type,
                        answer: answer
                    };
                } else if (type === 0 || type === 3 || type === 1) {
                    let answer = [];
                    let options = [];
                    for (let subjectOption of item.question.optionList) {
                        const opt = formatString(subjectOption.questionContent);
                        options.push(opt);
                    }
                    if (type === 1) {
                        item.question.questionAnswer.split(",").map(i => {
                            answer.push(options[i.toUpperCase().charCodeAt(0) - 65]);
                        });
                    } else {
                        answer.push(options[item.question.questionAnswer.toUpperCase().charCodeAt(0) - 65]);
                    }
                    return {
                        question: formatString(item.question.questionTitle),
                        options: options,
                        type: type,
                        answer: answer
                    };
                }
            });
        });
    }
    function parseShihuaExam(problems) {
        return problems.partitions.map(item => item.questions.map(item => {
            const type = getQuestionType(item.queTypeName);
            let answer = [];
            let options = [];
            if (type === 2) {
                answer.push(item.answer);
                return {
                    question: formatString(item.stem),
                    options: options,
                    type: type,
                    answer: answer
                };
            } else if (type === 0 || type === 3 || type === 1) {
                let answer = [];
                let options = [];
                if (type === 3) {
                    options = [ "对", "错" ];
                } else {
                    item.options.map(i => {
                        const opt = formatString(i.optInfo);
                        options.push(opt);
                    });
                }
                if (type === 1) {
                    item.answer.split(",").map(i => {
                        answer.push(options[i - 0]);
                    });
                } else if (type === 3) {
                    if (item.answer === "Y") {
                        answer = [ "对" ];
                    } else {
                        answer = [ "错" ];
                    }
                } else {
                    answer.push(options[item.answer - 0]);
                }
                return {
                    question: formatString(item.stem),
                    options: options,
                    type: type,
                    answer: answer
                };
            }
        }));
    }
